Here is the commit message:
util/range.c: spelling fix: inbetween
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Fixes: b439595a08d7 "range: Introduce range_inverse_array()"
Reviewed-by: Eric Auger <eric.auger@redhat.com>
Reviewed-by: Cédric Le Goater <clg@redhat.com>
Signed-off-by: Michael Tokarev <mjt@tls.msk.ru>

Here is the root cause:
The bug was a spelling error in a comment, where "inbetween" was incorrectly used instead of "in between". This could lead to confusion for developers reading the code, potentially causing misunderstandings about the functionality of the `range_inverse_array()` function. While it does not affect the code execution, it detracts from code clarity and documentation quality.

Here is the patch:

 void range_inverse_array(GList *in, GList **rev,
                          uint64_t low, uint64_t high)
 {
     Range *r, *rn;
     GList *l = in, *out = *rev;

     for (l = in; l && range_upb(l->data) < low; l = l->next) {
         continue;
     }

     if (!l) {
         out = append_new_range(out, low, high);
         goto exit;
     }
     r = (Range *)l->data;

     /* first range lob is greater than min, insert a first range */
     if (range_lob(r) > low) {
         out = append_new_range(out, low, MIN(range_lob(r) - 1, high));
     }

-    /* insert a range inbetween each original range until we reach high */
+    /* insert a range in between each original range until we reach high */
     for (; l->next; l = l->next) {
         r = (Range *)l->data;
         rn = (Range *)l->next->data;
         if (range_lob(r) >= high) {
             goto exit;
         }
         if (range_compare(r, rn)) {
             out = append_new_range(out, range_upb(r) + 1,
                                    MIN(range_lob(rn) - 1, high));
         }
     }

     /* last range */
     r = (Range *)l->data;

     /* last range upb is less than max, insert a last range */
     if (range_upb(r) <  high) {
         out = append_new_range(out, range_upb(r) + 1, high);
     }
 exit:
     *rev = out;
 }
